func (m *Model[T]) Update(msg tea.Msg) tea.Cmd {
	if m.bar.InEditMode() {
		var cmd tea.Cmd
		m.bar, cmd = m.bar.Update(msg)
		m.rebuild()
		// A search that keeps only short values has to give the room back, or
		// the filter buys nothing visually. It is a user action on a settled
		// population, which is exactly a measurement moment.
		m.Remeasure()
		return cmd
	}

	key, ok := msg.(tea.KeyMsg)
	if !ok {
		return nil
	}
	switch key.String() {
	case "/":
		// A table with nothing to search does not claim the key: activating a
		// search that can only ever match nothing would empty the list, and the
		// bar the user needs to see why is not in that view's footer.
		if !m.Searchable() {
			return nil
		}
		return m.bar.ActivateSearch()
	case ".":
		m.CycleSort()
	// No bare letter is navigation (§3.26). The vim aliases h/j/k/l/g/G are
	// gone application-wide: home/end already covered g/G, and keeping j/k
	// alone would leave the one exception that makes the rule unverifiable.
	// The letters now belong to the action vocabulary — internal/ui/keymap.
	case "up":
		m.table.MoveUp(1)
		m.afterCursorMove()
	case "down":
		m.table.MoveDown(1)
		m.afterCursorMove()
	case "pgup":
		m.table.MoveUp(m.table.Height())
		m.afterCursorMove()
	case "pgdown":
		m.table.MoveDown(m.table.Height())
		m.afterCursorMove()
	case "home":
		m.table.GotoTop()
		m.afterCursorMove()
	case "end":
		m.table.GotoBottom()
		m.afterCursorMove()
	}
	return nil
}

package command

import (
	"maps"
	"sort"
	"strings"
)

// ViewType représente le type de vue
type ViewType string

const (
	ViewDashboard ViewType = "dashboard"
	ViewStatus    ViewType = "status"
	// ViewGitAuth and ViewGitExplorer are named after the *role*, not after a
	// platform: a context targets one forge (§3.6), so there is one
	// authentication screen and one explorer, and both adapt to whichever it
	// is. A `gitlab-` prefix would have to be typed as `github-` half the time
	// for the same view.
	ViewGitAuth       ViewType = "git-auth"
	ViewGitExplorer   ViewType = "git-explorer"
	ViewWorkspaces    ViewType = "workspaces"
	ViewSecurity      ViewType = "security"
	ViewContainers    ViewType = "containers"
	ViewOCIResources  ViewType = "oci-resources"
	ViewNetdiag       ViewType = "netdiag"
