s = s.replace(old, new, 1)

if '"github.com/anthnel/devdesk/internal/jobs"' not in s:
    marker = '"github.com/anthnel/devdesk/internal/ui/keymap"'
    assert marker in s
    s = s.replace(marker, '"github.com/anthnel/devdesk/internal/jobs"\n\t' + marker, 1)

io.open(p, 'w', encoding='utf-8', newline='').write(s)
